import type { HandleArray, MainModule, DataModel, Display, AnnotationModel, Brush, ClassHandle, Data, Menu, Image, SharedImageSet, Graph, vec3, vec3i, Bindings, GlViewState, GlObject, AlignedBox, AlgorithmList, Mesh, FileFormat } from '../wasm/ImFusionLib.js';
/**
 * The main ImFusion Web SDK interface.
 */
export interface ImFusion {
    /** Data model containing the loaded datasets */
    readonly dataModel: DataModel;
    /** The main display/rendering area */
    readonly display: Display;
    /** Annotation model containing the created annotations */
    readonly annotationModel: AnnotationModel;
    /** Brush tool for painting on images */
    readonly brush: Brush;
    /** List of {@link Algorithm | Algorithms} compatible with the given {@link Data} array */
    compatibleAlgorithms(data: Data[]): AlgorithmList;
    /**
     * Load data from a File.
     * @param options.format - The file format. If omitted, the SDK tries to automatically detect it from the filename extension, then file
     * content if no known extension is present.
     * @see [Object Ownership and Aliasing](/ownership)
     */
    loadFile(file: File, options?: {
        format?: FileFormat;
    }): Promise<HandleArray<Data>>;
    /**
     * Load a file from a URL.
     *
     * @param url - URL to fetch data from
     * @param options.onProgress - Callback called on download progress.
     * @param options.signal - Aborts the data fetch if the signal is aborted.
     * @param options.format - The file format. If omitted, the SDK tries to automatically detect it from the filename extension, then file
     * content if no known extension is present. The filename comes from the `Content-Disposition` header, falling back to the last URL component.
     * @see [Object Ownership and Aliasing](/ownership)
     * @see {@link prefetch}
     */
    loadFileFromUrl(url: string, options?: {
        format?: FileFormat;
        onProgress?: ProgressCallback;
        signal?: AbortSignal;
    }): Promise<HandleArray<Data>>;
    /**
     * Load related files together as one virtual folder.
     *
     * Use this for formats whose logical data depends on multiple files, such as
     * DICOM series or meshes with separate material or texture files.
     *
     * Each file's relative path inside the folder is preserved. For files produced by
     * `<input webkitdirectory>` this comes automatically from `webkitRelativePath`. Otherwise the file's
     * `name` is used (forward slashes in `name` are honored, e.g. `new File([blob], 'series-1/IM-0001.dcm')`).
     *
     * @param files - Array of files
     * @see [Object Ownership and Aliasing](/ownership)
     * @see {@link loadFolderFromUrls}
     */
    loadFolder(files: File[]): Promise<HandleArray<Data>>;
    /**
     * Load related files from URLs together as one virtual folder.
     *
     * Use this for formats whose logical data depends on multiple files, such as
     * DICOM series or meshes with separate material or texture files.
     *
     * Each URL's relative path inside the folder is inferred from the longest
     * common pathname prefix (truncated to a `/` boundary). So
     *
     * ```ts
     * imf.loadFolderFromUrls([
     *   'https://example.com/scans/123/A/1.dcm',
     *   'https://example.com/scans/123/A/2.dcm',
     *   'https://example.com/scans/123/B/1.dcm',
     * ]);
     * ```
     *
     * creates this virtual folder:
     *
     * ```text
     * virtual-folder/
     * ├── A/
     * │   ├── 1.dcm
     * │   └── 2.dcm
     * └── B/
     *     └── 1.dcm
     * ```
     *
     * Fetches run with bounded concurrency (default 6). Any URL already warmed
     * via {@link prefetch} is consumed from the cache. Aborting `options.signal`
     * cancels all in-flight fetches and rejects the operation.
     *
     * All URLs must share the same origin. If you need to combine files from
     * different origins, fetch them yourself and pass `File` objects to
     * {@link loadFolder}.
     *
     * @param urls - File URLs to fetch as a single virtual folder
     * @param options.onProgress - Aggregate download progress across all entries.
     * @param options.signal - Aborts all in-flight fetches if the signal is aborted.
     * @param options.concurrency - Maximum number of fetches in flight (default 6).
     * @see [Object Ownership and Aliasing](/ownership)
     * @see {@link prefetch}
     */
    loadFolderFromUrls(urls: ReadonlyArray<string>, options?: {
        onProgress?: ProgressCallback;
        signal?: AbortSignal;
        concurrency?: number;
    }): Promise<HandleArray<Data>>;
    /**
     * Load data from an ArrayBuffer.
     * @param buffer - The raw file data
     * @param filename - The filename. This is used for the dataset name if not otherwise specified,
     * and for detecting the file format if no format is explicitly provided.
     * @param options.format - The file format. If omitted, the SDK tries to automatically detect it from the filename extension, then file
     * content if no known extension is present.
     * @see [Object Ownership and Aliasing](/ownership)
     */
    loadBuffer(buffer: ArrayBufferLike, filename: string, options?: {
        format?: FileFormat;
    }): Promise<HandleArray<Data>>;
    /**
     * Show a dataset in the view group and center the view on it.
     */
    show(data: Data): void;
    /**
     * Show all datasets in the view group and center on the first one.
     */
    showAll(data: Data[]): void;
    /**
     * Convert a plain array of {@link ClassHandle | ClassHandles} into an alias-aware {@link HandleArray}.
     * @see [Object Ownership and Aliasing](/ownership)
     */
    asHandleArray<T extends ClassHandle>(arr: T[]): HandleArray<T>;
    /**
     * Register a callback for context menu events.
     * Called when the SDK returns a context menu from an input event.
     * @param callback - Receives the {@link Menu} and the Event that triggered it.
     * @returns Unsubscribe function
     */
    onContextMenu(callback: (menu: Menu, event: Event) => void): () => void;
    /** Render the display */
    render(): void;
    /**
     * Pause automatic rendering.
     */
    pauseAutoRender(): void;
    /**
     * Resume automatic rendering.
     */
    resumeAutoRender(): void;
    /** Whether auto-render is currently paused */
    readonly isAutoRenderPaused: boolean;
    /** Get the current DPI scale factor */
    readonly dpiScale: number;
    /** Update the DPI scale factor and refresh the display */
    setDpiScale(scale: number): void;
    /** Update the display size */
    updateSize(): void;
    /**
     * Pause automatic canvas resizing.
     */
    pauseAutoResize(): void;
    /**
     * Resume automatic canvas resizing and apply any pending size updates.
     */
    resumeAutoResize(): void;
    /** Whether auto-resize is currently paused */
    readonly isAutoResizePaused: boolean;
    /**
     * Create a custom object that can be added to the {@link Display}
     * @param customGlObject - the CustomGlObject to wrap in a GlObject
     * @param typeName - Unique identifier for this object class used for serialization
     * @returns A custom Gl Object that can be added to individual views via {@link View#addObject | View.addObject()}
     * @warning **Memory Management**: The created GlObject is owned by JavaScript and must be cleaned up by calling `object.delete()`
     * after removing it from the views via {@link View#removeObject | View.removeObject()}
     * @see [Custom Rendering tutorial](/custom-rendering) for more information about integrating your own custom rendering into ImFusion Web SDK displays.
     */
    createCustomGlObject(customGlObject: CustomGlObject, typeName: string): GlObject;
    /**
     * Create an {@link Image} from raw pixel data.
     *
     * This is a convenience method that wraps {@link ImageDescriptor} and
     * {@link Image | Image.fromTypedArray} constructors.
     *
     * @param options - Image creation options
     * @returns The created {@link Image}, or null if creation failed
     *
     * @example
     * ```ts
     * const data = new Float32Array(256 * 256 * 100);
     * // ... fill data with pixel values ...
     *
     * using image = imf.createImage({
     *   dimensions: [256, 256, 100],
     *   channels: 1,
     *   data,
     * });
     * ```
     *
     * @warning **Memory Management**: The created image is owned by JavaScript and must be cleaned up:
     * - **Manual cleanup**: Call `image.delete()` when done
     * - **Explicit Resource Management** (TypeScript 5.2+): Use `using image = imf.createImage(...)`
     *
     * @see [Object Ownership and Aliasing](/ownership).
     */
    createImage(options: CreateImageOptions): Image | null;
    /**
     * Create a {@link SharedImageSet}.
     *
     * @param images - Array of {@link Image Images} to add to the set
     * @returns A new {@link SharedImageSet} containing the provided images
     *
     * @example
     * ```ts
     * using image = imf.createImage({ ... });
     * using sis = imf.createSharedImageSet([image!]);
     * imf.dataModel.add(sis); // persist the image in the data model
     * imf.show(sis);
     * ```
     *
     * @warning **Memory Management**: The created SharedImageSet is owned by JavaScript and must be cleaned up:
     * - **Manual cleanup**: Call `sis.delete()` when done
     * - **Explicit Resource Management** (TypeScript 5.2+): Use `using sis = imf.createSharedImageSet(...)`
     *
     * @see [Object Ownership and Aliasing](/ownership).
     */
    createSharedImageSet(images?: Image[]): SharedImageSet;
    /**
     * Create an empty {@link Graph}.
     *
     * @param options - Graph creation options. `type` defaults to `'Undirected'` and `dimension` defaults to
     * `'Dimension3D'`.
     * @returns A new {@link Graph}
     *
     * @remarks **Memory Management**: The created graph is owned by JavaScript and must be cleaned up:
     * - **Manual cleanup**: Call `graph.delete()` when done
     * - **Explicit Resource Management** (TypeScript 5.2+): Use `using graph = imf.createGraph()`
     *
     * @see [Object Ownership and Aliasing](/ownership).
     */
    createGraph(options?: ConstructorParameters<Bindings['Graph']>[0]): Graph;
    /**
     * Create an empty {@link Mesh}.
     *
     * @param options - Mesh creation options. `name` defaults to `''`
     * @returns A new {@link Mesh}
     *
     * @remarks **Memory Management**: The created mesh is owned by JavaScript and must be cleaned up:
     * - **Manual cleanup**: Call `mesh.delete()` when done
     * - **Explicit Resource Management** (TypeScript 5.2+): Use `using mesh = imf.createMesh()`
     *
     * @see [Object Ownership and Aliasing](/ownership).
     */
    createMesh(options?: Parameters<Bindings['Mesh']['create']>[0]): Mesh;
    /**
     * Release browser-side resources (ResizeObserver, canvas event listeners,
     * pending animation frames).
     */
    destroy(): void;
    /** The C++ API exposed to JavaScript, for functionality not covered by this interface */
    readonly bindings: Bindings;
    /**
     * Access the WASM filesystem.
     * @see [Emscripten File System API](https://emscripten.org/docs/api_reference/Filesystem-API.html)
     */
    readonly FS: MainModule['FS'];
    /** The canvas the SDK renders into */
    readonly canvas: HTMLCanvasElement;
}
/**
 * Options for initializing the ImFusion Web SDK wrapper.
 */
export interface InitOptions {
    /**
     * DPI scale factor for high-resolution displays.
     * @default window.devicePixelRatio
     */
    dpiScale?: number;
    /**
     * Automatically call {@link ImFusion#render | render()} when the SDK requests a display update.
     * @see {@link Display.onUpdateRequested}.
     * @default true
     */
    autoRender?: boolean;
    /**
     * Automatically handle canvas resize events.
     * Updates display size and triggers re-render when the canvas container resizes.
     * @default true
     */
    autoResize?: boolean;
    /**
     * Automatically forward DOM input events (mouse, touch, wheel) to the SDK.
     * @default true
     */
    autoInputHandling?: boolean;
    /**
     * Enable or disable UI animations.
     * Can also be changed through {@link Bindings.enableAnimations | imf.bindings.enableAnimations()}.
     * @default true
     */
    uiAnimations?: boolean;
    /**
     * Animate layout changes, such as maximizing a view or changing the layout mode.
     * Can also be changed through {@link Display.layouter | display.layouter().animationsEnabled}.
     * @remarks This option is evaluated *in addition* to the global {@link InitOptions.uiAnimations | uiAnimations} setting and both
     * must be enabled in order to animate layout changes.
     * @default false
     */
    layoutAnimations?: boolean;
    /**
     * License token to activate full features and remove the watermark.
     */
    licenseToken?: string;
}
/**
 * Options for creating an {@link Image} from pixel data (see {@link ImFusion#createImage | createImage()}).
 */
export interface CreateImageOptions {
    /**
     * Image dimensions as [width, height, slices].
     */
    dimensions: vec3i;
    /**
     * Number of channels per pixel.
     */
    channels: number;
    /**
     * Pixel data as a TypedArray. The array length must match:
     * `width * height * slices * channels`
     */
    data: Parameters<Bindings['Image']['fromTypedArray']>[1];
    /**
     * Physical pixel/voxel spacing in mm.
     */
    spacing?: vec3;
}
/**
 * Interface for defining a custom GL Object
 * @see {@link ImFusion.createCustomGlObject}
 */
export interface CustomGlObject {
    render: (viewState: GlViewState) => void;
    bounds: () => AlignedBox;
}
/**
 * Callback called on download progress.
 *
 * @param received - Bytes received so far
 * @param total - Total bytes (null if unknown)
 * @see {@link ImFusion.loadFileFromUrl}, {@link ImFusion.loadFolderFromUrls}
 */
export type ProgressCallback = (received: number, total: number | null) => void;
